import{_ as t,o as r,c as l,a0 as o}from"./chunks/framework.ZoVXsKRZ.js";const c=JSON.parse('{"title":"🕵️ 防老千秘籍","description":"","frontmatter":{"lastUpdated":true},"headers":[],"relativePath":"skills/anti-cheat.md","filePath":"skills/anti-cheat.md","lastUpdated":1784794489000}'),i={name:"skills/anti-cheat.md"};function n(s,a,e,h,g,d){return r(),l("div",null,[...a[0]||(a[0]=[o('<h1 id="🕵️-防老千秘籍" tabindex="-1">🕵️ 防老千秘籍 <a class="header-anchor" href="#🕵️-防老千秘籍" aria-label="Permalink to &quot;🕵️ 防老千秘籍&quot;">​</a></h1><p>麻将桌上，赢了开心，输了也认。<strong>但被出千输了，那就不是运气问题了。</strong></p><p>这篇汇总了常见的麻将出千手法和识别技巧，<strong>不是在教你出千，而是在帮你防千</strong>。</p><hr><h2 id="⚠️-写在前面" tabindex="-1">⚠️ 写在前面 <a class="header-anchor" href="#⚠️-写在前面" aria-label="Permalink to &quot;⚠️ 写在前面&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">重要提醒</p><p>出千属于<strong>欺诈行为</strong>，严重者可能触犯法律。本文仅供<strong>识破千术、保护自己</strong>之用。请勿利用本文内容进行任何违法行为。</p></div><hr><h2 id="🃏-常见出千手法" tabindex="-1">🃏 常见出千手法 <a class="header-anchor" href="#🃏-常见出千手法" aria-label="Permalink to &quot;🃏 常见出千手法&quot;">​</a></h2><h3 id="一、洗牌阶段" tabindex="-1">一、洗牌阶段 <a class="header-anchor" href="#一、洗牌阶段" aria-label="Permalink to &quot;一、洗牌阶段&quot;">​</a></h3><h4 id="_1-码牌做记" tabindex="-1">1. 码牌做记 <a class="header-anchor" href="#_1-码牌做记" aria-label="Permalink to &quot;1. 码牌做记&quot;">​</a></h4><ul><li><strong>手法</strong>：洗牌时用指甲在牌背划痕，或用手指按压留下凹痕</li><li><strong>目的</strong>：记住关键牌的位置</li><li><strong>识别</strong>：查看牌背是否有痕迹；换一副新牌</li></ul><h4 id="_2-弹洗控牌" tabindex="-1">2. 弹洗控牌 <a class="header-anchor" href="#_2-弹洗控牌" aria-label="Permalink to &quot;2. 弹洗控牌&quot;">​</a></h4><ul><li><strong>手法</strong>：洗牌时将特定牌洗到自己想要的位置</li><li><strong>目的</strong>：起手就有好牌</li><li><strong>识别</strong>：注意洗牌时是否有「刻意」动作；要求每人切牌</li></ul><h4 id="_3-偷换牌" tabindex="-1">3. 偷换牌 <a class="header-anchor" href="#_3-偷换牌" aria-label="Permalink to &quot;3. 偷换牌&quot;">​</a></h4><ul><li><strong>手法</strong>：趁人不注意，将手伸到桌下或裤兜，换上预先藏好的牌</li><li><strong>目的</strong>：瞬间改变牌型</li><li><strong>识别</strong>：注意对手手部是否频繁离开桌面</li></ul><hr><h3 id="二、摸牌阶段" tabindex="-1">二、摸牌阶段 <a class="header-anchor" href="#二、摸牌阶段" aria-label="Permalink to &quot;二、摸牌阶段&quot;">​</a></h3><h4 id="_4-偷看牌" tabindex="-1">4. 偷看牌 <a class="header-anchor" href="#_4-偷看牌" aria-label="Permalink to &quot;4. 偷看牌&quot;">​</a></h4><ul><li><strong>手法</strong>：摸牌时用拇指摸牌面，感知牌面刻痕</li><li><strong>目的</strong>：提前知道摸到什么牌再决定要不要</li><li><strong>识别</strong>：观察摸牌时拇指是否有「感知」动作；正规麻将牌面平滑</li></ul><h4 id="_5-藏牌" tabindex="-1">5. 藏牌 <a class="header-anchor" href="#_5-藏牌" aria-label="Permalink to &quot;5. 藏牌&quot;">​</a></h4><ul><li><strong>手法</strong>：将摸到的牌藏入手心、袖口或腿上</li><li><strong>目的</strong>：减少手牌、或留作他用</li><li><strong>识别</strong>：打完一局数牌数（每人门前应该是 13/14 张）</li></ul><hr><h3 id="三、出牌阶段" tabindex="-1">三、出牌阶段 <a class="header-anchor" href="#三、出牌阶段" aria-label="Permalink to &quot;三、出牌阶段&quot;">​</a></h3><h4 id="_6-明暗勾兑-两人配合" tabindex="-1">6. 明暗勾兑（两人配合） <a class="header-anchor" href="#_6-明暗勾兑-两人配合" aria-label="Permalink to &quot;6. 明暗勾兑（两人配合）&quot;">​</a></h4><div class="warning custom-block"><p class="custom-block-title">高发骗局</p><p>这是最常见的组队骗局，一定要小心！</p></div><ul><li><strong>手法</strong>：两人事先约定暗号（摸鼻子=要万子，摸耳朵=要筒子等）</li><li><strong>目的</strong>：互相喂牌、联合做牌</li><li><strong>识别</strong>： <ul><li>注意是否有人频繁做「多余」的小动作</li><li>某两人之间碰吃频率是否异常高</li><li>注意出牌是否有规律（总在给固定的人喂牌）</li></ul></li></ul><h4 id="_7-掉包计" tabindex="-1">7. 掉包计 <a class="header-anchor" href="#_7-掉包计" aria-label="Permalink to &quot;7. 掉包计&quot;">​</a></h4><ul><li><strong>手法</strong>：摸牌后快速将手中的废牌替换成摸到的牌</li><li><strong>目的</strong>：偷换牌</li><li><strong>识别</strong>：注意摸牌→看牌→放入手牌的完整动作是否流畅自然</li></ul><hr><h2 id="🛡️-防千自查清单" tabindex="-1">🛡️ 防千自查清单 <a class="header-anchor" href="#🛡️-防千自查清单" aria-label="Permalink to &quot;🛡️ 防千自查清单&quot;">​</a></h2><p>线下打牌时，对照这个清单快速检查：</p><ul><li>[ ] <strong>是否使用新牌？</strong> 全新未拆封的麻将牌，降低做记风险</li><li>[ ] <strong>牌桌是否整洁？</strong> 杂物越少，藏牌空间越小</li><li>[ ] <strong>是否有人频繁离席？</strong> 去厕所/打电话太多次要警惕</li><li>[ ] <strong>是否有人牌不放在桌上？</strong> 手放到桌下是出千大忌</li><li>[ ] <strong>同桌是否有「配合」感？</strong> 两人出牌频率异常的要留意</li><li>[ ] <strong>每局结束数牌数？</strong> 养成核对的习惯</li><li>[ ] <strong>自动麻将桌是否正常？</strong> 程序麻将桌是高科技千术</li></ul><hr><h2 id="🤖-科技千术-自动麻将桌作弊" tabindex="-1">🤖 科技千术：自动麻将桌作弊 <a class="header-anchor" href="#🤖-科技千术-自动麻将桌作弊" aria-label="Permalink to &quot;🤖 科技千术：自动麻将桌作弊&quot;">​</a></h2><p>随着自动麻将桌的普及，出现了更隐蔽的千术：</p><h3 id="常见手法" tabindex="-1">常见手法 <a class="header-anchor" href="#常见手法" aria-label="Permalink to &quot;常见手法&quot;">​</a></h3><ol><li><strong>程序控制</strong>：在麻将桌主板植入芯片，控制洗牌结果</li><li><strong>遥控操作</strong>：利用遥控器发信号，某些牌会被洗到指定位置</li><li><strong>透视麻将</strong>：配合特殊麻将牌 + 隐形眼镜，能看穿牌面</li></ol><h3 id="如何防范" tabindex="-1">如何防范 <a class="header-anchor" href="#如何防范" aria-label="Permalink to &quot;如何防范&quot;">​</a></h3><ul><li>优先选择<strong>正规棋牌室</strong>，知名连锁品牌更可靠</li><li>自己<strong>带一副麻将</strong>去不熟的局</li><li>注意自动麻将桌是否有<strong>异常声音或卡顿</strong></li><li><strong>不熟的人邀请</strong>去私人民宅打牌，原则上婉拒</li></ul><hr><h2 id="🤝-心理博弈技巧-合法的" tabindex="-1">🤝 心理博弈技巧（合法的） <a class="header-anchor" href="#🤝-心理博弈技巧-合法的" aria-label="Permalink to &quot;🤝 心理博弈技巧（合法的）&quot;">​</a></h2><p>不是千术，但能帮你在牌桌上保持清醒：</p><ul><li><strong>控制情绪</strong>：喜怒不形于色，摸到好牌不要笑、摸到坏牌不要皱眉</li><li><strong>调整节奏</strong>：不要总用相同速度出牌，否则对手能猜出你的牌</li><li><strong>观察微表情</strong>：对手摸牌后嘴角上扬？大概率是好牌</li><li><strong>记住关键牌</strong>：至少记住已经出了哪些字牌和关键花色</li></ul><hr><h2 id="📝-总结" tabindex="-1">📝 总结 <a class="header-anchor" href="#📝-总结" aria-label="Permalink to &quot;📝 总结&quot;">​</a></h2><blockquote><p><strong>十赌九骗，不赌为赢。</strong></p><p>打麻将是为了娱乐和社交，不要抱着赢钱的心态。和熟悉的朋友打，去正规的棋牌室，才是安全又开心的麻将打开方式。</p></blockquote><p>如果受到千术侵害，请保存证据并及时报警。</p><hr><p><em>记住：这篇文章的目的是保护你，而不是教你骗人。</em></p>',49)])])}const b=t(i,[["render",n]]);export{c as __pageData,b as default};
